// The watched-states 1.1 duty: the additive watched stamp on every serving
// route the task names — the scored listing (stamped from the batched facts
// the score already composed), the single-item GET (the route that composes
// no facts today gains the recsFactsFor composition), the sort=path opt-out
// (ledger set ALONE — rec_score stays absent, store order untouched), the
// per-series episode rows (composition gained, narrative order kept,
// unscored), and the progress rows under the scored default — plus the
// true-only omitempty semantics (field absent on the wire for unwatched
// rows). All asserted over the REAL router wiring and a real store, the
// repo's handler-test idiom (newRecsAPI + seedRecs* helpers).
func TestWatchedItemStamp(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// Films: one ledgered, one not — their id order puts the unwatched one
	// first, so a sort=path stamp cannot be an order accident.
	plainFilm := seedRecsItem(t, st, lib, "wst_pf", "a-plain.mkv", map[string]any{}, time.Time{})
	watchedFilm := seedRecsItem(t, st, lib, "wst_wf", "b-watched.mkv", map[string]any{}, time.Time{})
	if err := st.InsertWatched(ctx, watchedFilm.ID, lib, "", time.Now().UTC()); err != nil {
		t.Fatalf("InsertWatched film: %v", err)
	}
	// A series with one ledgered and one fresh episode — the episode table
	// must split exactly on the ledger while keeping narrative order.
	show := seedRecsSeries(t, st, lib, "wshow", recsSeriesDoc("WShow"))
	epWatched := seedRecsItem(t, st, lib, "wst_e1", "wshow/e1.mkv", recsEpisodeDoc("wshow", ""), time.Time{})
	epFresh := seedRecsItem(t, st, lib, "wst_e2", "wshow/e2.mkv", recsEpisodeDoc("wshow", ""), time.Time{})
	if err := st.InsertWatched(ctx, epWatched.ID, lib, "wshow", time.Now().UTC()); err != nil {
		t.Fatalf("InsertWatched episode: %v", err)
	}
	// The progress surface: the watched episode's row keeps its positive
	// position beside the ledger row (the detector writes the ledger beside
	// the position), and the plain film carries an unwatched row — so the
	// scored default rail serves exactly one watched and one unwatched row.
	if _, err := st.PutProgress(ctx, epWatched.ID, 300); err != nil {
		t.Fatalf("PutProgress episode: %v", err)
	}
	if _, err := st.PutProgress(ctx, plainFilm.ID, 120); err != nil {
		t.Fatalf("PutProgress film: %v", err)
	}

	// wireFlags re-marshals one wire row and reports which of the additive
	// watched-states fields rode it (the omitempty probes, as in the recs
	// goldens' wireHasRecScore).
	wireFlags := func(t *testing.T, d any) (watched, recScore bool) {
		t.Helper()
		b, err := json.Marshal(d)
		if err != nil {
			t.Fatalf("remarshal wire row: %v", err)
		}
		var wire map[string]any
		if err := json.Unmarshal(b, &wire); err != nil {
			t.Fatalf("unmarshal wire row: %v", err)
		}
		_, watched = wire["watched"]
		_, recScore = wire["rec_score"]
		return watched, recScore
	}

	// stampRow is one surface row reduced to id + opaque DTO — item rows and
	// progress rows share it, so one table covers both wire shapes.
	type stampRow struct {
		id  string
		dto any
	}
	itemRows := func(t *testing.T, resp *http.Response) []stampRow {
		t.Helper()
		lr := decodeItems(t, resp)
		rows := make([]stampRow, len(lr.Items))
		for i, d := range lr.Items {
			rows[i] = stampRow{d.ID, d}
		}
		return rows
	}
	singleRow := func(t *testing.T, resp *http.Response) []stampRow {
		t.Helper()
		var ir itemResponse
		if err := json.NewDecoder(resp.Body).Decode(&ir); err != nil {
			t.Fatalf("decode itemResponse: %v", err)
		}
		return []stampRow{{ir.Item.ID, ir.Item}}
	}
	progressRows := func(t *testing.T, resp *http.Response) []stampRow {
		t.Helper()
		lr := decodeProgressList(t, resp)
		rows := make([]stampRow, len(lr.Items))
		for i, d := range lr.Items {
			rows[i] = stampRow{d.ItemID, d}
		}
		return rows
	}

	tcs := []struct {
		name     string
		url      string
		rows     func(t *testing.T, resp *http.Response) []stampRow
		watched  map[string]bool // id → watched must ride the wire; every served row not listed here must NOT carry it
		unscored bool            // rec_score must stay off EVERY row of the surface
		order    []string        // when non-nil, the exact served id order
	}{
		{
			name: "scored_listing_stamps_from_the_batched_facts",
			url:  "/api/v1/items?library=" + itoa64(lib),
			rows: itemRows,
			watched: map[string]bool{
				watchedFilm.ID: true,
				epWatched.ID:   true,
			},
		},
		{
			name:     "single_item_get_gains_the_composition",
			url:      "/api/v1/items/" + watchedFilm.ID,
			rows:     singleRow,
			watched:  map[string]bool{watchedFilm.ID: true},
			unscored: true, // the detail route never carries rec_score
		},
		{
			name:     "single_item_get_unwatched_absent",
			url:      "/api/v1/items/" + plainFilm.ID,
			rows:     singleRow,
			watched:  map[string]bool{},
			unscored: true,
		},
		{
			name:     "episode_rows_stamp_narrative_order_kept_unscored",
			url:      "/api/v1/series/" + show.ID + "/episodes",
			rows:     itemRows,
			watched:  map[string]bool{epWatched.ID: true},
			unscored: true,
			order:    []string{epWatched.ID, epFresh.ID},
		},
		{
			name: "sort_path_stamps_from_the_ledger_alone",
			url:  "/api/v1/items?library=" + itoa64(lib) + "&sort=path",
			rows: itemRows,
			watched: map[string]bool{
				watchedFilm.ID: true,
				epWatched.ID:   true,
			},
			unscored: true,
			// QueryItems' id-ordered SQL window, byte for byte — the stamp
			// must not have reordered it.
			order: []string{epWatched.ID, epFresh.ID, plainFilm.ID, watchedFilm.ID},
		},
		{
			name: "progress_rows_stamp_from_the_batched_facts",
			url:  "/api/v1/progress",
			rows: progressRows,
			watched: map[string]bool{
				epWatched.ID: true,
			},
		},
	}

	for _, tc := range tcs {
		t.Run(tc.name, func(t *testing.T) {
			resp := doRequest(t, h, http.MethodGet, tc.url, "", adminToken)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("status = %d, want 200", resp.StatusCode)
			}
			rows := tc.rows(t, resp)
			if tc.order != nil {
				got := make([]string, len(rows))
				for i, r := range rows {
					got[i] = r.id
				}
				wantIDs(t, got, tc.order...)
			}
			for _, r := range rows {
				watched, recScore := wireFlags(t, r.dto)
				if watched != tc.watched[r.id] {
					t.Fatalf("row %s: watched on wire = %v, want %v", r.id, watched, tc.watched[r.id])
				}
				if tc.unscored && recScore {
					t.Fatalf("row %s served rec_score — the surface must stay unscored", r.id)
				}
			}
		})
	}
}
